use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SnippetVersionSnippetAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class SnippetVersionSnippetAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getSnippet returns null on a freshly created holder.
     */
    public function testSnippetNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithSnippetVersionSnippetAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isSnippetAssigned());
        $this->assertNull($holder->getSnippet());
    }
}
class ImplWithSnippetVersionSnippetAttributeHolderUnitTest
